]

def get_value(r, c):
    """Predicted value at position (r,c)"""
    if c % 3 == 0:
        return 8
    elif c % 3 == 1:
        # Pattern with 7
        band = c // 3
        if band % 2 == 0:
            return 8 if r % 2 == 0 else 7
        else:
            return 7 if r % 2 == 0 else 8
    else:  # c % 3 == 2
        # Pattern with 4
        band = c // 3
        if band % 2 == 0:
            return 4 if r % 2 == 0 else 8
        else:
            return 8 if r % 2 == 0 else 4

# Verify pattern against non-5 values
print("Verifying pattern against non-5 values:")
all_match = True
for r in range(11):
    for c in range(16):
        v = grid[r][c]
        if v == 5:
            continue
        exp = get_value(r, c)
        if v != exp:
            print(f"  FAIL: grid[{r}][{c}]={v}, predicted={exp}")
            all_match = False

if all_match:
    print("Pattern verified!")

# Now reconstruct the full grid
output = []
for r in range(11):
    row = []
    for c in range(16):
        if grid[r][c] != 5:
            row.append(grid[r][c])
        else:
            row.append(get_value(r, c))
    output.append(row)

print("\nReconstructed output:")
for r in range(11):
    print(f"Row {r}: {output[r]}")

